create table public.projects(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete restrict,campus_id uuid references public.campuses(id) on delete restrict,title text not null,summary text not null default '',body text not null default '',category text not null,status text not null default 'draft',visibility text not null default 'campus',created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),deleted_at timestamptz,constraint projects_status check(status in('draft','open','active','completed','archived','removed')),constraint projects_visibility check(visibility in('private','campus','public')));
create table public.project_members(project_id uuid not null references public.projects(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,member_role text not null,status text not null default 'requested',message text not null default '',created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),primary key(project_id,user_id),constraint project_member_status check(status in('requested','invited','active','rejected','removed')));
create table public.project_skills(project_id uuid not null references public.projects(id) on delete cascade,skill_id uuid not null references public.skills(id) on delete restrict,requirement_level smallint,created_at timestamptz not null default timezone('utc',now()),primary key(project_id,skill_id));
create table public.project_media(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,media_asset_id uuid not null references public.media_assets(id) on delete restrict,position smallint not null,created_at timestamptz not null default timezone('utc',now()),unique(project_id,position));
create table public.campaigns(id uuid primary key default gen_random_uuid(),project_id uuid not null unique references public.projects(id) on delete restrict,creator_id uuid not null references public.profiles(id) on delete restrict,goal_amount numeric(14,2) not null,currency char(3) not null default 'INR',starts_at timestamptz not null,ends_at timestamptz not null,status text not null default 'draft',created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),constraint campaign_amount check(goal_amount>0),constraint campaign_dates check(ends_at>starts_at),constraint campaign_status check(status in('draft','active','paused','completed','cancelled')));
create table public.campaign_contributions(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references public.campaigns(id) on delete restrict,contributor_id uuid references public.profiles(id) on delete restrict,amount numeric(14,2) not null,currency char(3) not null,payment_reference text unique,status text not null default 'pending',created_at timestamptz not null default timezone('utc',now()),constraint contribution_amount check(amount>0),constraint contribution_status check(status in('pending','authorized','settled','failed','refunded')));
create table public.campaign_updates(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references public.campaigns(id) on delete cascade,author_id uuid not null references public.profiles(id) on delete restrict,body text not null,published_at timestamptz,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()));
create table public.payment_transactions(id uuid primary key default gen_random_uuid(),payer_id uuid references public.profiles(id) on delete restrict,purpose_type text not null,purpose_id uuid not null,provider text not null,provider_reference text not null,amount numeric(14,2) not null,currency char(3) not null,status text not null,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(provider,provider_reference),constraint payment_amount check(amount>0));
create index projects_owner_idx on public.projects(owner_id,status); create index project_members_user_idx on public.project_members(user_id,status); create index campaign_contributions_campaign_idx on public.campaign_contributions(campaign_id,created_at); create index payment_transactions_payer_idx on public.payment_transactions(payer_id,created_at desc);
alter table public.projects enable row level security; alter table public.project_members enable row level security; alter table public.project_skills enable row level security; alter table public.project_media enable row level security; alter table public.campaigns enable row level security; alter table public.campaign_contributions enable row level security; alter table public.campaign_updates enable row level security; alter table public.payment_transactions enable row level security;
create policy projects_read on public.projects for select to authenticated using(owner_id=auth.uid() or (deleted_at is null and visibility<>'private') or public.has_permission('projects.moderate',campus_id)); create policy projects_owner on public.projects for all to authenticated using(owner_id=auth.uid() or public.has_permission('projects.moderate',campus_id)) with check(owner_id=auth.uid() or public.has_permission('projects.moderate',campus_id)); create policy project_members_read on public.project_members for select to authenticated using(user_id=auth.uid() or exists(select 1 from public.projects p where p.id=project_id and p.owner_id=auth.uid())); create policy project_members_write on public.project_members for all to authenticated using(user_id=auth.uid() or exists(select 1 from public.projects p where p.id=project_id and p.owner_id=auth.uid())) with check(user_id=auth.uid() or exists(select 1 from public.projects p where p.id=project_id and p.owner_id=auth.uid())); create policy project_skills_read on public.project_skills for select to authenticated using(true); create policy project_skills_owner on public.project_skills for all to authenticated using(exists(select 1 from public.projects p where p.id=project_id and p.owner_id=auth.uid())) with check(exists(select 1 from public.projects p where p.id=project_id and p.owner_id=auth.uid())); create policy project_media_read on public.project_media for select to authenticated using(true); create policy project_media_owner on public.project_media for all to authenticated using(exists(select 1 from public.projects p where p.id=project_id and p.owner_id=auth.uid())) with check(exists(select 1 from public.projects p where p.id=project_id and p.owner_id=auth.uid())); create policy campaigns_read on public.campaigns for select to authenticated using(status='active' or creator_id=auth.uid()); create policy campaigns_manage on public.campaigns for all to authenticated using(creator_id=auth.uid() or public.has_permission('crowdfunding.manage')) with check(creator_id=auth.uid() or public.has_permission('crowdfunding.manage')); create policy contributions_read on public.campaign_contributions for select to authenticated using(contributor_id=auth.uid() or public.has_permission('crowdfunding.manage')); create policy contributions_trusted on public.campaign_contributions for insert to authenticated with check(false); create policy campaign_updates_read on public.campaign_updates for select to authenticated using(true); create policy campaign_updates_owner on public.campaign_updates for all to authenticated using(exists(select 1 from public.campaigns c where c.id=campaign_id and c.creator_id=auth.uid())) with check(exists(select 1 from public.campaigns c where c.id=campaign_id and c.creator_id=auth.uid())); create policy payments_read on public.payment_transactions for select to authenticated using(payer_id=auth.uid() or public.has_permission('payments.read'));
